theorem main_estimate :
    let n := ∑ i, x i
    let q : ℤ := ((n / 6 : ℕ) : ℤ)
    let r : ℤ := ((n % 6 : ℕ) : ℤ)
    let d : Fin 6 → ℤ := fun i => (x i : ℤ) - q
    let D : ℤ := ∑ i, d i * (d i - 1)
    (∑ i, d i = r) ∧ (0 ≤ D) ∧
      ((exS6 n : ℤ) - s6Count x = D * q + sig r - s6Z d) ∧
      (18 * ((exS6 n : ℤ) - s6Count x) ≥ (n : ℤ) * D -
        (2 * r * (6 - r) * q + r ^ 2 * (r - 1) - 18 * sig r))

lemma class_eq_of_isEdge_map {i : Fin 6} {a b c : V}
    (h : ((G i).map (Function.Embedding.subtype (fun v => f v = i))).IsEdge a b c) :
    f a = i ∧ f b = i ∧ f c = i

lemma dotProduct_mulVec_weightedMatrix_le_one {S : Matrix ι ι ℝ} {w : ι → ℝ}
    (hS : IsSignMatrix S) (hw : IsWeight w) {u : ι → ℝ} (hu : u ⬝ᵥ u = 1) :
    u ⬝ᵥ (weightedMatrix S w *ᵥ u) ≤ 1

theorem stationary (hA : ∀ i j, A j i = A i j) (h : IsOrthonormalPair u v)
    (hmax : ∀ x y, IsOrthonormalPair x y → fanValue A x y ≤ fanValue A u v) {z : ι → ℝ}
    (hzu : z ⬝ᵥ u = 0) (hzv : z ⬝ᵥ v = 0) : z ⬝ᵥ (A *ᵥ u) = 0

theorem sumTopTwo_eq_of_charpoly_eq_X_mul {A : Matrix ι ι ℝ} {B : Matrix κ κ ℝ}
    (hA : A.IsHermitian) (hB : B.IsHermitian) (h : A.charpoly = X * B.charpoly) {a b : ι}
    (hab : a ≠ b) (ha : ∀ j, hA.eigenvalues j ≤ hA.eigenvalues a)
    (hb : ∀ j, j ≠ a → hA.eigenvalues j ≤ hA.eigenvalues b) (hpos : 0 < hA.eigenvalues b) :
    π₂ B = π₂ A

lemma dotProduct_signedExtend {f : ι → κ} (hf : Function.Injective f) {ε : ι → ℝ}
    (hε : ∀ i, ε i * ε i = 1) (x y : ι → ℝ) :
    signedExtend f ε x ⬝ᵥ signedExtend f ε y = x ⬝ᵥ y

theorem sumTopTwo_weightedMatrix_eq_of_equiv {S : Matrix ι ι ℝ} {T : Matrix κ κ ℝ} {w : ι → ℝ}
    (hS : IsSignMatrix S) (hT : IsSignMatrix T) (hw : IsWeight w) (e : ι ≃ κ) {ε : ι → ℝ}
    (hε : ∀ i, ε i * ε i = 1) (hST : ∀ i j, S i j = ε i * ε j * T (e i) (e j)) :
    π₂ (weightedMatrix S w) = π₂ (weightedMatrix T (w ∘ e.symm))

theorem exists_mem_orthProjs_range (Y : Submodule 𝕜 (ι → 𝕜)) {m : ℕ}
    (hm : Module.finrank 𝕜 Y = m) :
    ∃ P ∈ orthProjs 𝕜 ι m, LinearMap.range (Matrix.toLin' P) = Y

theorem exists_parseval_range (Y : Submodule 𝕜 (ι → 𝕜)) {r : ℕ}
    (hr : Module.finrank 𝕜 Y = r) :
    ∃ U : Matrix (Fin r) ι 𝕜, U * Uᴴ = 1 ∧ LinearMap.range (Matrix.toLin' Uᴴ) = Y

theorem clConst_eq_sSup_parseval (m : ℕ) :
    clConst 𝕜 ι m = sSup {x | ∃ (t : ι → ℝ) (U : Matrix (Fin m) ι 𝕜), (∀ i, 0 ≤ t i) ∧
      ∑ i, t i ^ 2 = 1 ∧ U * Uᴴ = 1 ∧ x = ∑ i, ∑ j, t i * t j * ‖(Uᴴ * U) i j‖}

theorem quasiRelConst_eq_sSup_parseval (m : ℕ) :
    quasiRelConst 𝕜 ι m = sSup {x | ∃ U : Matrix (Fin m) ι 𝕜, U * Uᴴ = 1 ∧
      x = (1 / Fintype.card ι) * ∑ i, ∑ j, ‖(Uᴴ * U) i j‖}

theorem maxProjConst_eq_iSup {𝕜 : Type} [RCLike 𝕜] {m : ℕ} {L : ℝ}
    (hL : ∀ N, maxRelProjConst 𝕜 m N ≤ L) :
    maxProjConst 𝕜 m = ⨆ N, maxRelProjConst 𝕜 m N

theorem relProjConst_le_absProjConst (hL : ∀ N, maxRelProjConst 𝕜 m N ≤ L) {X : Type u}
    [NormedAddCommGroup X] [NormedSpace 𝕜 X] (Y : Submodule 𝕜 X) [FiniteDimensional 𝕜 Y]
    (hY : Module.finrank 𝕜 Y = m) : relProjConst Y ≤ absProjConst 𝕜 Y

theorem relProjConst_le_maxProjConst {𝕜 : Type} [RCLike 𝕜] {m : ℕ} {L : ℝ}
    (hL : ∀ N, maxRelProjConst 𝕜 m N ≤ L) {N : ℕ} (Y : Submodule 𝕜 (Fin N → 𝕜))
    (hY : Module.finrank 𝕜 Y = m) : relProjConst Y ≤ maxProjConst 𝕜 m

theorem relProjConst_le_of_maxRelProjConst_le {m : ℕ} {L : ℝ}
    (hL : ∀ N, maxRelProjConst 𝕜 m N ≤ L) (Y : Submodule 𝕜 X) [FiniteDimensional 𝕜 Y]
    (hY : Module.finrank 𝕜 Y = m) : relProjConst Y ≤ L

theorem isClique4_iff {S : Matrix ι ι ℝ} (hS : IsSignMatrix S) {a b c d : ι} :
    IsClique4 S a b c d ↔ (a ≠ b ∧ a ≠ c ∧ a ≠ d ∧ b ≠ c ∧ b ≠ d ∧ c ≠ d) ∧
      IsClique S {a, b, c, d}

theorem twoGraph_submatrix [Fintype κ] [DecidableEq κ] {T : Matrix κ κ ℝ}
    (hT : IsSignMatrix T) (f : ι → κ) :
    twoGraph (T.submatrix f f) = (twoGraph T).pullback f

theorem injective_of_switchEquiv_submatrix {S : Matrix ι ι ℝ} {T : Matrix κ κ ℝ} {f : ι → κ}
    (h : SwitchEquiv S (T.submatrix f f)) (htw : ∀ i j, ¬IsTwin S i j) :
    Function.Injective f

theorem switchEquiv_of_twoGraph_eq [Fintype ι] [DecidableEq ι] {S T : Matrix ι ι ℝ}
    (hS : IsSignMatrix S) (hT : IsSignMatrix T) (h : twoGraph S = twoGraph T) :
    SwitchEquiv S T

theorem scalar_sub_weightedR5 (s : Fin 5 → ℝ) (x : ℝ) :
    scalar (Fin 5) x - weightedR5 s =
      !![x - s 0 * s 0, s 0 * s 1, -(s 0 * s 2), -(s 0 * s 3), s 0 * s 4;
         s 1 * s 0, x - s 1 * s 1, s 1 * s 2, -(s 1 * s 3), -(s 1 * s 4);
         -(s 2 * s 0), s 2 * s 1, x - s 2 * s 2, s 2 * s 3, -(s 2 * s 4);
         -(s 3 * s 0), -(s 3 * s 1), s 3 * s 2, x - s 3 * s 3, s 3 * s 4;
         s 4 * s 0, -(s 4 * s 1), -(s 4 * s 2), s 4 * s 3, x - s 4 * s 4]

theorem IsMaximizingPair.sum_abs_mul {U : Matrix (Fin n) (Fin r) ℝ} {w : Fin n → ℝ}
    (h : IsMaximizingPair U w) (i : Fin n) :
    ∑ j, |U i ⬝ᵥ U j| * w j = maxRelProjConst ℝ r n * w i

theorem IsMaximizingPair.trace_mul_le (h : IsMaximizingPair U w) {Q : Matrix (Fin n) (Fin n) ℝ}
    (hQ : Q ∈ orthProjs ℝ (Fin n) r) :
    (weightedSign U w * Q).trace ≤ (weightedSign U w * (U * Uᵀ)).trace

theorem not_signPattern_A6_of_switch {ι : Type*} {S : Matrix ι ι ℝ} {u v : ι → ℝ}
    (h : ∀ i j, 0 < S i j * (u i * u j + v i * v j)) (ψ : Fin 6 → ι) (δ : Fin 6 → ℝ)
    (hδ : ∀ a, δ a * δ a = 1) (hψ : ∀ a b, S (ψ a) (ψ b) = δ a * δ b * A6 a b) : False

lemma isCoclique_preimage {S : Matrix ι ι ℝ} {T : Matrix κ κ ℝ} {f : ι → κ} {ε : ι → ℝ}
    (hε : IsSignVector ε) (hST : ∀ i j, S i j = ε i * ε j * T (f i) (f j)) {C : Set κ}
    (hC : IsCoclique T C) : IsCoclique S (f ⁻¹' C)

theorem sumTopTwo_weightedMatrix_le_one_of_eq_mul {S : Matrix ι ι ℝ} {ε : ι → ℝ}
    (hε : ∀ i, ε i * ε i = 1) (hS : ∀ i j, S i j = ε i * ε j) {w : ι → ℝ} (hw : IsWeight w) :
    π₂ (weightedMatrix S w) ≤ 1

theorem kmmp_cloning {n r : ℕ} {U : Matrix (Fin n) (Fin r) ℝ} {w : Fin n → ℝ}
    (h : KMMP.IsMaximizingPair U w) (hr : 0 < r) {C : Finset (Fin n)}
    (hC : ∀ i ∈ C, ∀ j ∈ C, 0 ≤ U i ⬝ᵥ U j) {c : Fin n → ℝ} (hc : ∀ i, 0 ≤ c i)
    (hc1 : ∀ i, i ∉ C → c i = 1)
    (hcC : ∑ i ∈ C, c i • vecMulVec (U i) (U i) = ∑ i ∈ C, vecMulVec (U i) (U i)) :
    KMMP.IsMaximizingPair (KMMP.cloneMatrix U c) (KMMP.cloneWeight w c)

theorem lemma_C {m : ℕ} (hm : 2 < m) {S : Matrix (Fin m) (Fin m) ℝ} {w : Fin m → ℝ}
    (hmax : IsMaximizer S w) (hpos : ∀ i, 0 < w i) {u v : Fin m → ℝ}
    (huv : IsOrthonormalPair u v)
    (hval : fanValue (weightedMatrix S w) u v = π₂ (weightedMatrix S w)) {C : Finset (Fin m)}
    (hC : ∀ i ∈ C, ∀ j ∈ C, 0 ≤ u i * u j + v i * v j) {c : Fin m → ℝ} (hc : ∀ i, 0 ≤ c i)
    (hc1 : ∀ i, i ∉ C → c i = 1)
    (hcC : ∑ i ∈ C, c i • vecMulVec ![u i, v i] ![u i, v i] =
      ∑ i ∈ C, vecMulVec ![u i, v i] ![u i, v i]) :
    IsWeight (fun i => c i * w i) ∧ IsMaximizer S fun i => c i * w i

theorem lemma_D (u v : Fin 6 → ℝ) (σ : Equiv.Perm (Fin 6)) {ε : Fin 6 → ℝ}
    (hε : IsSignVector ε) :
    ¬∀ i j, 0 < ε i * ε j * A6 (σ i) (σ j) * (u i * u j + v i * v j)

theorem supWeights_switch_relabel {ι κ : Type*} [Fintype ι] [Fintype κ] {S : Matrix ι ι ℝ}
    {T : Matrix κ κ ℝ} (hS : IsSignMatrix S) (hT : IsSignMatrix T) (e : ι ≃ κ) {ε : ι → ℝ}
    (hε : IsSignVector ε) (hST : ∀ i j, S i j = ε i * ε j * T (e i) (e j)) :
    supWeights S = supWeights T
